script:
(function () {
  'use strict';
  // Net worth = total assets - total liabilities. Debt-to-asset ratio = liabilities / assets.
  // Projection: assets x (1 + g)^n and liabilities x (1 + c)^n, liabilities floored at $0.
  // Checks: default lists 488,000 - 290,000 = $198,000 net worth, ratio 290/488 = 59.4%;
  // in 10 years at +4% / -8%: 488,000 x 1.04^10 = 722,359.21 and 290,000 x 0.92^10 = 125,972.65,
  // net worth $596,386.56.
  // Row names are user text: they are only ever read from .value and written with textContent.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var MAX_ROWS = 25;
  var DEFAULT_ASSETS = [['Checking and savings', 15000], ['Retirement accounts', 85000], ['Brokerage investments', 20000], ['Home value', 350000], ['Vehicles', 18000]];
  var DEFAULT_DEBTS = [['Mortgage', 260000], ['Car loan', 12000], ['Student loans', 15000], ['Credit cards', 3000]];
  var rowCounter = 0;

  function project(assets, debts, growth, debtChange, years) {
    var rows = [];
    for (var y = 1; y <= years; y++) {
      var a = assets * Math.pow(1 + growth, y);
      var d = Math.max(0, debts * Math.pow(1 + debtChange, y));
      rows.push({ year: y, assets: a, debts: d, net: a - d });
    }
    return rows;
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clear(id) {
    var el = document.getElementById(id);
    while (el.firstChild) el.removeChild(el.firstChild);
    return el;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  function el(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }

  // kind: 'asset' or 'debt'
  function listFor(kind) { return document.getElementById(kind === 'asset' ? 'nwAssets' : 'nwDebts'); }

  function addLine(kind, name, amount) {
    var list = listFor(kind);
    rowCounter++;
    var n = rowCounter;
    var row = el('div', 'flex flex-wrap items-center gap-2');
    row.setAttribute('data-line', kind);

    var nameInput = el('input', 'form-control min-w-0 flex-[2_1_10rem]');
    nameInput.type = 'text'; nameInput.id = 'nwName' + n; nameInput.maxLength = 40; nameInput.autocomplete = 'off';
    nameInput.placeholder = kind === 'asset' ? 'e.g. Savings account' : 'e.g. Personal loan';
    nameInput.value = name;
    nameInput.setAttribute('data-name', '');

    var group = el('div', 'input-group min-w-0 flex-[1_1_8rem]');
    group.appendChild(el('span', 'input-affix', '$'));
    var amt = el('input', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    amt.type = 'number'; amt.id = 'nwAmt' + n; amt.min = '0'; amt.step = '100'; amt.inputMode = 'decimal';
    amt.value = amount === '' ? '' : String(amount);
    amt.setAttribute('data-amount', '');
    group.appendChild(amt);

    var remove = el('button', 'button-secondary h-9 px-3 text-sm', 'Remove');
    remove.type = 'button';
    remove.setAttribute('data-remove', '');
    remove.addEventListener('click', function () {
      list.removeChild(row);
      refreshRows(kind);
      update();
    });

    row.appendChild(nameInput); row.appendChild(group); row.appendChild(remove);
    list.appendChild(row);
    refreshRows(kind);
    return nameInput;
  }

  function refreshRows(kind) {
    var rows = listFor(kind).querySelectorAll('[data-line]');
    var word = kind === 'asset' ? 'Asset ' : 'Liability ';
    for (var i = 0; i < rows.length; i++) {
      rows[i].querySelector('[data-name]').setAttribute('aria-label', word + (i + 1) + ' name');
      rows[i].querySelector('[data-amount]').setAttribute('aria-label', word + (i + 1) + ' amount');
      rows[i].querySelector('[data-remove]').setAttribute('aria-label', 'Remove ' + word.toLowerCase() + (i + 1));
    }
    document.getElementById(kind === 'asset' ? 'nwAddAsset' : 'nwAddDebt').disabled = rows.length >= MAX_ROWS;
  }

  function readLines(kind) {
    var rows = listFor(kind).querySelectorAll('[data-line]'), out = [];
    var word = kind === 'asset' ? 'Asset ' : 'Liability ';
    for (var i = 0; i < rows.length; i++) {
      var raw = rows[i].querySelector('[data-amount]').value;
      var v = raw === '' ? 0 : parseFloat(raw);
      if (isNaN(v) || v < 0 || v > 1e12) return null;
      var name = rows[i].querySelector('[data-name]').value.trim() || word + (i + 1);
      out.push({ name: name, amount: v });
    }
    return out;
  }

  function sum(lines) { return lines.reduce(function (s, l) { return s + l.amount; }, 0); }

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function blank() {
    ['nwNet', 'nwAssetTotal', 'nwDebtTotal', 'nwRatio', 'nwFuture', 'nwYearsOut'].forEach(function (id) { set(id, '–'); });
    set('nwRatioNote', '');
    clear('nwBreakdown'); clear('nwProjection');
  }

  function update() {
    var assets = readLines('asset'), debts = readLines('debt');
    var growth = num('nwGrowth'), change = num('nwDebtChange'), years = num('nwYears');
    var msg = '';
    if (!assets || !debts) msg = 'Enter each amount as $0 or more.';
    else if (isNaN(growth) || growth < -50 || growth > 50) msg = 'Enter a yearly change in assets from -50% to 50%.';
    else if (isNaN(change) || change < -100 || change > 50) msg = 'Enter a yearly change in debts from -100% to 50%.';
    else if (isNaN(years) || years < 1 || years > 50 || Math.round(years) !== years) msg = 'Enter 1 to 50 whole years to project.';
    var error = document.getElementById('nwError');
    error.hidden = !msg;
    if (msg) { error.textContent = msg; blank(); return; }

    var a = sum(assets), d = sum(debts);
    set('nwNet', money.format(a - d));
    set('nwAssetTotal', money.format(a));
    set('nwDebtTotal', money.format(d));
    if (a > 0) {
      var ratio = d / a;
      set('nwRatio', (ratio * 100).toFixed(1) + '%');
      set('nwRatioNote', d === 0 ? 'No debts listed' : ratio > 1 ? 'You owe more than you own' : 'Share of your assets owed to lenders');
    } else {
      set('nwRatio', '–');
      set('nwRatioNote', d > 0 ? 'No assets listed' : '');
    }

    var body = clear('nwBreakdown');
    [[assets, 'Asset', a], [debts, 'Liability', d]].forEach(function (g) {
      g[0].slice().sort(function (x, y) { return y.amount - x.amount; }).forEach(function (l) {
        addRow(body, [l.name, g[1], money.format(l.amount), g[2] > 0 ? (l.amount / g[2] * 100).toFixed(1) + '%' : '–']);
      });
    });

    var rows = project(a, d, growth / 100, change / 100, years);
    var last = rows[rows.length - 1];
    set('nwYearsOut', years + (years === 1 ? ' year' : ' years'));
    set('nwFuture', money.format(last.net));
    var pb = clear('nwProjection');
    addRow(pb, ['Today', money.format(a), money.format(d), money.format(a - d)]);
    rows.forEach(function (r) {
      addRow(pb, [String(r.year), money.format(r.assets), money.format(r.debts), money.format(r.net)]);
    });
  }

  function wireAdd(kind, buttonId) {
    document.getElementById(buttonId).addEventListener('click', function () {
      if (listFor(kind).querySelectorAll('[data-line]').length >= MAX_ROWS) return;
      var input = addLine(kind, '', '');
      update();
      if (input.focus) input.focus();
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    DEFAULT_ASSETS.forEach(function (x) { addLine('asset', x[0], x[1]); });
    DEFAULT_DEBTS.forEach(function (x) { addLine('debt', x[0], x[1]); });
    wireAdd('asset', 'nwAddAsset');
    wireAdd('debt', 'nwAddDebt');
    var form = document.getElementById('nwForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
